"""Actualiza exclusivamente el informe técnico para los cuatro puntos de Persona 2."""
from pathlib import Path
import json

root = Path(__file__).resolve().parents[2]
path = root / 'docs/entrega/contenido-informes.json'
content = json.loads(path.read_text(encoding='utf-8'))
t = content['technical']['pages'][:8]
t[4]['paragraphs'][2] = 'La resolución documental se evalúa aparte de la presencia de citas. Un control conservador detecta remisiones y un evaluador LLM descompone la pregunta en aspectos completos, parciales o ausentes. Todos deben estar completos y respaldados por una cita literal de la respuesta. Si falla el evaluador, la consulta no cuenta como resuelta. La evaluación no cambia la respuesta visible ni añade trazas individuales. En consultas mixtas se verifica solo la política; la resolución final exige además el dato personal.'
t[4]['paragraphs'][3] = 'El campo resuelta de consultas_chat alimenta el porcentaje resuelto y la lista de vacíos del reporte. Las seis respuestas históricas parciales se comprobaron con el criterio nuevo, sin reescribir esos resultados ni reportes ya publicados. El control no certifica vigencia jurídica y puede infravalorar una respuesta legítima si el juez falla. El modo mock no acredita resolución documental. El coste adicional de esta comprobación debe incluirse en futuras mediciones de latencia.'
t[5]['paragraphs'] = [p for p in t[5]['paragraphs'] if not p.startswith('Chunking operativo:')]
t[5]['paragraphs'].append('Chunking operativo: ingestion.service.js divide cada sección con chunkText(part, 90, 20): noventa palabras y veinte de solapamiento, no tokens. El separador conserva encabezados. La recuperación filtra por firma de embeddings y umbral RAG_MIN_SCORE, considera hasta dos documentos y reúne secciones hasta mil cuatrocientas palabras. Estos valores difieren de la recomendación de quinientos a mil tokens del enunciado: son una decisión actual que debe evaluarse empíricamente, no una equivalencia de unidades.')
t[6]['paragraphs'][1] = 'Groq redacta ahora todas las frases del resumen: se solicitan cuatro, dentro del requisito de tres a cinco. La salida JSON contiene indicador y texto con un marcador de valor. Cada frase debe usar la etiqueta exacta del indicador; solo después se interpola el valor SQL. Se rechazan cantidades libres, indicadores repetidos, etiquetas intercambiadas y frases múltiples por elemento. El modo mock conserva una plantilla identificada. Un fallo de validación impide publicar el reporte; no se presenta una plantilla como redacción real del LLM.'
t[6]['paragraphs'][2] = 'Además del scheduler interno, se registró Nuvexa-RRHH-Reporte-0700 en el Programador de tareas de Windows, zona de Costa Rica. Inicia Node directamente sin depender del servidor web abierto. Requiere sesión iniciada y equipo encendido; una sesión bloqueada es válida. StartWhenAvailable permite recuperar una ejecución tardía, sin presentarla como cumplimiento puntual de las 7:00. La próxima ejecución registrada es el 20 de noviembre de 2026 a las 07:00. La prueba real de arranque a las 10:24 terminó con código cero y reutilizó el reporte existente.'
t[6]['paragraphs'][3] = 'scheduled-report.js conserva fecha y hora reales de inicio, zona, resultado, fecha de creación del reporte y proveedor en backend/.cache/scheduler. Solo una ejecución no manual iniciada a las 07:00 lleva observedAtSeven=true. El reporte diario conserva su bloqueo MySQL e idempotencia. La prueba manual valida conectividad y el ejecutable, pero no acredita la hora futura. El 19 de noviembre, después de las 7:00, la observación real de mañana seguía pendiente.'
t[7]['paragraphs'] = [
'La evaluación histórica de cuarenta y cinco preguntas sigue disponible con proveedor Voyage y Groq; su p90 de mil novecientos veinte milisegundos corresponde al código anterior. No se atribuye ese tiempo al nuevo evaluador. Las seis parciales pertenecen al banco original: diecinueve de veinticinco respuestas completas. Las correcciones de Persona 2 no publican políticas en Drive ni declaran alcanzado el umbral documental pendiente.',
'La batería local actual contiene treinta y cuatro pruebas: contratos de resumen y etiquetas, rechazo de números y longitudes inválidos, resolución por aspectos, errores del juez, datos propios, scheduler independiente, parsers y control de cuotas. La prueba específica verify-persona2.js usa Groq real y cifras de un reporte SQL existente para generar un borrador nuevo; verifica seis respuestas parciales y tres completas sin alterar reportes ni logs. Sus resultados están en validacion-persona2.json.',
'Pruebas HTTP: npm run test:integration verifica sesión, CSRF, separación de roles e identidad personal; no sustituye una evaluación semántica. El comando npm run verify:report contrasta cifras con SQL. Una prueba con reloj controlado demuestra independencia e idempotencia del scheduler, mientras que la tarea Windows permite recoger después la evidencia horaria real. Cada alcance se documenta por separado.',
'Las modificaciones de esta fase se limitan a resumen, métrica de resolución, ejecución automática e informe técnico. No se publicaron documentos, añadieron mejoras conversacionales ni modificaron preguntas o reglas de seguridad. Los reportes publicados y la evaluación histórica se conservan. Los anexos reproducen los prompts reales; datos e ingesta usan contratos deterministas y no precisan un prompt LLM propio.'
]
for filename, title in [('orchestrator.txt','9. Prompt del orquestador'),('policy.txt','10. Prompt de selección documental'),('analyst.txt','11. Prompt del analista'),('resolution.txt','12. Prompt de evaluación de resolución')]:
    prompt = (root / 'backend/prompts' / filename).read_text(encoding='utf-8').strip()
    paragraphs = [f'Fuente versionada: backend/prompts/{filename}. Se reproduce el contrato utilizado por el servicio, sin credenciales.']
    paragraphs += [line for line in prompt.splitlines() if line.strip()]
    if filename == 'orchestrator.txt':
        paragraphs += ['Agente de datos: recibe la identidad autenticada y una consulta; utiliza SQL de solo lectura por ID. Devuelve answer, resolved, escalated, citations y fragmentIds. No inventa políticas ni necesita un prompt LLM. Datos ausentes o solicitudes ambiguas no se marcan como resueltos.', 'Agente de ingesta: recibe inventario y cambios de Drive, extrae texto, prepara fragmentos y embeddings y actualiza catálogo e índice. Su salida informa archivos ingeridos o conservados y cantidad de fragmentos. Es un pipeline determinista, sin prompt LLM; la cuenta operativa sigue siendo de lectura.']
    t.append({'title':title,'paragraphs':paragraphs})
content['technical']['pages'] = t
path.write_text(json.dumps(content,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Informe técnico actualizado: doce secciones y cuatro prompts reales.')
